import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;import java.util.*;import java.util.zip.*;import java.nio.file.*;
public class Patch implements Opcodes{
 static int hooks;static final String DEC="dev/zomboid/decor/";
 static MethodInsnNode call(String owner,String n,String d){return new MethodInsnNode(INVOKESTATIC,owner,n,d,false);}
 static byte[] patch(byte[] b,String kind)throws Exception{ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);int before=hooks;
 for(MethodNode m:c.methods){
  if(kind.equals("decor")&&c.name.equals("net/mcreator/doomsdaydecoration/block/PortedAcrateBlock")&&m.name.equals("getTicker"))for(AbstractInsnNode a:m.instructions)if(a instanceof MethodInsnNode mc&&mc.owner.equals(DEC+"Cooling")&&mc.name.equals("ticker")){mc.owner=DEC+"Climate";hooks++;}
  if(kind.equals("decor")&&c.name.equals("net/mcreator/doomsdaydecoration/block/entity/AcrateBlockEntity")&&m.name.equals("canPlaceItem"))for(AbstractInsnNode a:m.instructions)if(a instanceof MethodInsnNode mc&&mc.owner.equals(DEC+"Cooling")&&mc.name.equals("accepts")){mc.owner=DEC+"Climate";hooks++;}
  if(kind.equals("decor")&&c.name.equals(DEC+"ModEvents")&&m.name.equals("register")){for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==RETURN){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(call(DEC+"Climate","register","(Ljava/lang/Object;)V"));m.instructions.insertBefore(a,x);hooks++;}}
  if(kind.equals("decor")&&c.name.equals(DEC+"GameEvents")&&m.name.equals("tick")){for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==RETURN){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(call(DEC+"Climate","migrate","(Ljava/lang/Object;)V"));m.instructions.insertBefore(a,x);hooks++;}}
  if(kind.equals("homeo")&&c.name.equals("homeostatic/common/temperature/BodyTemperature")&&m.name.equals("<init>")&&m.desc.contains("ZZ")){for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==RETURN){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,1));x.add(new VarInsnNode(ALOAD,0));x.add(call("dev/zomboid/homeoac/Link","body","(Ljava/lang/Object;Ljava/lang/Object;)V"));m.instructions.insertBefore(a,x);hooks++;}}
  if(kind.equals("homeo")&&c.name.equals("homeostatic/common/temperature/EnvironmentData")&&m.name.equals("<init>")){for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==RETURN){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,1));x.add(new VarInsnNode(ALOAD,0));x.add(call("dev/zomboid/homeoac/Link","environment","(Ljava/lang/Object;Ljava/lang/Object;)V"));m.instructions.insertBefore(a,x);hooks++;}}
  if(kind.equals("homeo")&&c.name.equals("homeostatic/network/Temperature")&&m.name.equals("checkTemperatureLevel")){early(m,"dev/zomboid/homeoac/Link","data",new int[]{1,0});hooks++;}
  if(kind.equals("tan")&&c.name.equals("toughasnails/temperature/TemperatureHandler")&&m.name.equals("onPlayerTick")){early(m,"dev/zomboid/tanac/Link","player",new int[]{0});hooks++;}
  if(kind.equals("hordes")&&c.name.equals("dev/zomboid/hordes/SiegeZombie")&&m.name.equals("breakBlock"))for(AbstractInsnNode a:m.instructions.toArray())if(a instanceof MethodInsnNode mc&&mc.owner.equals("dev/zomboid/hordes/BreachSettings")&&mc.name.equals("breakTicks")){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,1));x.add(new VarInsnNode(ALOAD,3));x.add(call("dev/zomboid/hordes/BarricadeLink","ticks","(ILjava/lang/Object;Ljava/lang/Object;)I"));m.instructions.insert(a,x);hooks++;}
  if(kind.equals("hordes")&&c.name.equals("dev/zomboid/hordes/BarrierBreakGoal")&&m.name.equals("canUse"))for(AbstractInsnNode a:m.instructions.toArray())if(a instanceof FieldInsnNode f&&f.getOpcode()==PUTFIELD&&f.name.equals("duration")){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new VarInsnNode(ALOAD,0));x.add(new FieldInsnNode(GETFIELD,c.name,"duration","I"));x.add(new VarInsnNode(ALOAD,0));x.add(new FieldInsnNode(GETFIELD,c.name,"mob","Lnet/minecraft/world/entity/Mob;"));x.add(new MethodInsnNode(INVOKEVIRTUAL,"net/minecraft/world/entity/Mob","level","()Lnet/minecraft/world/level/Level;",false));x.add(new VarInsnNode(ALOAD,0));x.add(new FieldInsnNode(GETFIELD,c.name,"pos","Lnet/minecraft/core/BlockPos;"));x.add(call("dev/zomboid/hordes/BarricadeLink","ticks","(ILjava/lang/Object;Ljava/lang/Object;)I"));x.add(new FieldInsnNode(PUTFIELD,c.name,"duration","I"));m.instructions.insert(a,x);hooks++;}
 }
 if(before==hooks)return b;ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);ClassNode v=new ClassNode();new ClassReader(w.toByteArray()).accept(v,0);for(MethodNode m:v.methods)if((m.access&(ACC_NATIVE|ACC_ABSTRACT))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(v.name,m);return w.toByteArray();}
 static void early(MethodNode m,String owner,String name,int[] slots){InsnList x=new InsnList();for(int i:slots)x.add(new VarInsnNode(ALOAD,i));x.add(call(owner,name,slots.length==1?"(Ljava/lang/Object;)Z":"(Ljava/lang/Object;Ljava/lang/Object;)Z"));LabelNode original=new LabelNode();x.add(new JumpInsnNode(IFEQ,original));x.add(new InsnNode(RETURN));x.add(original);x.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(x);}
 static byte[] events(){ClassWriter w=new ClassWriter(0);String owner=DEC+"ClimateEvents";w.visit(V21,ACC_PUBLIC|ACC_FINAL,owner,null,"java/lang/Object",null);AnnotationVisitor a=w.visitAnnotation("Lnet/neoforged/fml/common/EventBusSubscriber;",true);a.visit("modid","doomsday_decoration");a.visitEnd();for(String[] spec:new String[][]{{"grow","net/neoforged/neoforge/event/level/block/CropGrowEvent$Post","Climate"},{"breaking","net/neoforged/neoforge/event/entity/player/PlayerEvent$BreakSpeed","Boards"}}){MethodVisitor m=w.visitMethod(ACC_PUBLIC|ACC_STATIC,spec[0],"(L"+spec[1]+";)V",null,null);m.visitAnnotation("Lnet/neoforged/bus/api/SubscribeEvent;",true).visitEnd();m.visitCode();m.visitVarInsn(ALOAD,0);m.visitMethodInsn(INVOKESTATIC,DEC+spec[2],spec[0],"(Ljava/lang/Object;)V",false);m.visitInsn(RETURN);m.visitMaxs(1,1);m.visitEnd();}w.visitEnd();return w.toByteArray();}
 public static void main(String[]a)throws Exception{Map<String,byte[]>out=new TreeMap<>();try(ZipFile z=new ZipFile(a[0])){for(ZipEntry e:Collections.list(z.entries())){byte[]b=z.getInputStream(e).readAllBytes();out.put(e.getName(),e.getName().endsWith(".class")?patch(b,a[3]):b);}}try(var files=Files.walk(Path.of(a[2]))){for(Path p:files.filter(p->p.toString().endsWith(".class")).toList())out.put(Path.of(a[2]).relativize(p).toString(),Files.readAllBytes(p));}if(a[3].equals("decor"))out.put(DEC+"ClimateEvents.class",events());int expected=switch(a[3]){case "decor"->4;case "homeo"->3;case "hordes"->2;case "tan"->1;default->0;};if(hooks!=expected)throw new IllegalStateException(a[3]+" hooks "+hooks+" expected "+expected);try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var e:out.entrySet()){ZipEntry n=new ZipEntry(e.getKey());n.setTime(0);z.putNextEntry(n);z.write(e.getValue());z.closeEntry();}}System.out.println(a[3]+" hooks verified: "+hooks);}
}
